def pi_brute(x: float) -> int:
    """Compute pi(x) by sieving (small x only)."""
    n = int(x)
    if n < 2:
        return 0
    sieve = bytearray(b"\x01" * (n + 1))
    sieve[0] = 0
    sieve[1] = 0
    for i in range(2, int(math.isqrt(n)) + 1):
        if sieve[i]:
            sieve[i * i::i] = b"\x00" * (((n - i * i) // i) + 1)
    return sum(sieve)


